SELECT (EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.save_question_bank_drafts(jsonb)') AND md5(replace(prosrc,E'\r',''))='b5b637db4e84aa4e59989781931c26f5') AND EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.update_question_bank_draft_metadata(uuid,uuid,text,jsonb)') AND md5(replace(prosrc,E'\r',''))='9ee58df274c0e5ced38aae588e8571d0') AND EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.question_bank_content_issues(uuid,uuid)') AND md5(replace(prosrc,E'\r',''))='ee312839e62d85504beafaef696efcda')) AND EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261105020000' AND name='question_bank_legacy_arena_source' AND cardinality(statements)=1 AND md5(statements[1])='819f451763686ddcaadb5e79b0e845c7') AND NOT has_function_privilege('authenticated','public.question_bank_legacy_arena_source(jsonb,text)','EXECUTE') AND NOT has_function_privilege('anon','public.question_bank_legacy_arena_source(jsonb,text)','EXECUTE') AND EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.question_versions'::regclass AND conname='question_versions_source_page_kind' AND convalidated) AS all_checks_pass;
